## 调度器选择

正确选择 Dispatcher 对性能和 ANR 避免至关重要。

```kotlin
class ArticleRepository @Inject constructor(
    private val api: ArticleApi,
    private val dao: ArticleDao,
    @IoDispatcher private val ioDispatcher: CoroutineDispatcher
) {
    suspend fun getArticles(): List<Article> = withContext(ioDispatcher) {
        try {
            val remote = api.getArticles()
            dao.insertAll(remote.data?.map { it.toEntity() } ?: emptyList())
            remote.data?.map { it.toDomain() } ?: emptyList()
        } catch (e: Exception) {
            dao.getAll().first().map { it.toDomain() }
        }
    }

    suspend fun processImage(bitmap: Bitmap): Bitmap = withContext(Dispatchers.Default) {
        // CPU 密集型图像处理
        bitmap.scale(bitmap.width / 2, bitmap.height / 2)
    }
}

@Module
@InstallIn(SingletonComponent::class)
object DispatcherModule {

    @IoDispatcher
    @Provides
    fun provideIoDispatcher(): CoroutineDispatcher = Dispatchers.IO

    @DefaultDispatcher
    @Provides
    fun provideDefaultDispatcher(): CoroutineDispatcher = Dispatchers.Default

    @MainDispatcher
    @Provides
    fun provideMainDispatcher(): CoroutineDispatcher = Dispatchers.Main
}

@Qualifier
@Retention(AnnotationRetention.BINARY)
annotation class IoDispatcher

@Qualifier
@Retention(AnnotationRetention.BINARY)
annotation class DefaultDispatcher

@Qualifier
@Retention(AnnotationRetention.BINARY)
annotation class MainDispatcher
```

