## 取消与结构化并发

协程的结构化并发确保子协程在父协程取消时一并取消。

```kotlin
@HiltViewModel
class SearchViewModel @Inject constructor(
    private val repository: SearchRepository
) : ViewModel() {

    private var searchJob: Job? = null

    fun search(query: String) {
        searchJob?.cancel()
        searchJob = viewModelScope.launch {
            delay(300) // debounce
            val results = repository.search(query)
            _searchResults.value = results
        }
    }

    fun parallelLoad() {
        viewModelScope.launch {
            val (articles, users, tags) = coroutineScope {
                val articlesDeferred = async { repository.getArticles() }
                val usersDeferred = async { repository.getUsers() }
                val tagsDeferred = async { repository.getTags() }
                Triple(
                    articlesDeferred.await(),
                    usersDeferred.await(),
                    tagsDeferred.await()
                )
            }
            _uiState.update {
                it.copy(articles = articles, users = users, tags = tags)
            }
        }
    }
}
```

